    display: block;
    margin-top: 4px;
    color: rgba(var(--sa-text-dim),0.5);
}

/* ── Chart section ───────────────────────────────────────────────────────────── */

.sa-chart-section {
    background: var(--sa-surface-3, rgba(26,26,36,0.92));
    border: 1px solid var(--sa-border, rgba(255,255,255,0.055));
    border-radius: var(--sa-radius, 12px);
    padding: 22px 24px 20px;
    box-shadow: var(--sa-shadow-panel);
}

.sa-area-chart { width: 100%; }

.sa-chart-section__hd {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    margin-bottom: 16px;
    gap: 12px;
}

.sa-chart-section__title {
    margin: 0;
    font-size: 0.82rem;
    font-weight: 600;
    letter-spacing: 0;
    text-transform: none;
    color: rgba(var(--sa-text),0.9);
    display: flex;
    align-items: center;
    gap: 7px;
}

.sa-chart-section__period {
    font-size: 0.69rem;
    color: rgba(130,130,150,0.6);
    white-space: nowrap;
}

.sa-chart {
    width: 100%;
    height: auto;
    position: relative;
}

.sa-chart--empty {
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.875rem;
    color: rgba(var(--sa-text-dim),0.6);
}

.sa-chart__legend {
    display: flex;
    align-items: center;
    gap: 6px;
    margin-top: 8px;
    font-size: 0.7rem;
    color: rgba(var(--sa-text-dim),0.65);
}

.sa-chart__legend-dot {
    width: 8px;
    height: 8px;
    border-radius: 2px;
    flex-shrink: 0;
}

.sa-chart__legend-dot--full    { background: rgba(74,222,128,0.75); }
.sa-chart__legend-dot--minimal { background: rgba(var(--sa-accent),0.55); }

.sa-trend-insights {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin-top: 10px;
}

.sa-trend-insights__chip {
    font-size: 0.72rem;
    color: rgba(var(--sa-text-muted),0.75);
    background: rgba(255,255,255,0.04);
    border: 1px solid rgba(255,255,255,0.07);
    border-radius: 8px;
    padding: 4px 10px;
}

.sa-trend-insights__chip b {
    color: #ececec;
    font-weight: 700;
}

/* ── Dashboard grid ──────────────────────────────────────────────────────────── */

.sa-dashboard-grid {
    display: grid;
    gap: 12px;
    align-items: start;
    grid-template-columns: repeat(4, 1fr);
    grid-template-areas:
        "kpi1   kpi2    kpi3      kpi4"
        "chart  chart   chart     live"
        "pages  pages   consent   countries"
        "brows  brows   utm       utm"
        "os     os      screens   screens";
}

.sa-dashboard-grid--no-utm {
    grid-template-areas:
        "kpi1   kpi2    kpi3      kpi4"
        "chart  chart   chart     live"
        "pages  pages   consent   countries"
        "brows  brows   os        screens";
}

/* Grid area assignments */
.sa-ga-kpi0      { grid-area: kpi0; }
.sa-ga-kpi1      { grid-area: kpi1; }
.sa-ga-kpi2      { grid-area: kpi2; }
.sa-ga-kpi3      { grid-area: kpi3; }
.sa-ga-kpi4      { grid-area: kpi4; }
.sa-ga-kpi5      { grid-area: kpi5; }
.sa-ga-chart     { grid-area: chart; align-self: start; }
.sa-ga-live      { grid-area: live; }
.sa-ga-pages     { grid-area: pages; }
.sa-ga-consent   { grid-area: consent; }
.sa-ga-countries { grid-area: countries; }
.sa-ga-brows     { grid-area: brows; }
.sa-ga-utm       { grid-area: utm; }
.sa-ga-os        { grid-area: os; }
.sa-ga-screens   { grid-area: screens; }

@media (max-width: 1100px) {
    .sa-dashboard-grid,
    .sa-dashboard-grid--no-utm {
        grid-template-columns: repeat(2, 1fr);
        grid-template-areas:
            "kpi1    kpi2"
            "kpi3    kpi4"
            "chart   chart"
            "live    live"
            "pages   pages"
            "consent countries"
            "brows   utm"
            "os      screens";
    }
    .sa-dashboard-grid--no-utm {
        grid-template-areas:
            "kpi1    kpi2"
            "kpi3    kpi4"
            "chart   chart"
            "live    live"
            "pages   pages"
            "consent countries"
            "brows   brows"
            "os      screens";
    }
}

@media (max-width: 620px) {
    .sa-dashboard-grid,
    .sa-dashboard-grid--no-utm {
        grid-template-columns: 1fr;
        grid-template-areas:
            "kpi1" "kpi2" "kpi3" "kpi4"
            "chart" "live"
            "pages" "consent" "countries"
            "brows" "utm" "os" "screens";
    }
}

/* ── Generic panel card ──────────────────────────────────────────────────────── */

.sa-panel {
    background: var(--sa-surface-3, rgba(26,26,36,0.92));
    border: 1px solid var(--sa-border, rgba(255,255,255,0.055));
    border-radius: var(--sa-radius, 12px);
    padding: 20px 22px;
    box-shadow: var(--sa-shadow-panel);
}

.sa-panel__title {
    margin: 0 0 14px;
    font-size: 0.78rem;
    font-weight: 600;
    letter-spacing: 0;
    text-transform: none;
    color: rgba(var(--sa-text),0.85);
    display: flex;
    align-items: center;
    gap: 8px;
}

/* Divider between stacked sub-sections within a panel */
.sa-panel__divider {
    height: 1px;
    background: rgba(255,255,255,0.06);
    margin: 14px 0;
}

.sa-panel__sub-title {
    margin: 0 0 10px;
    font-size: 0.69rem;
    font-weight: 600;
    letter-spacing: 0;
    text-transform: none;
    color: rgba(var(--sa-text-dim),0.6);
}

.sa-panel__consent-note {
    font-size: 0.62rem;
    font-weight: 500;
    color: rgba(var(--sa-text-dim),0.55);
    text-transform: none;
    letter-spacing: 0;
    margin-left: 4px;
}

.sa-panel__footer-link {
    display: inline-block;
    margin-top: 12px;
    font-size: 0.78rem;
    font-weight: 600;
    color: rgba(var(--sa-accent),0.9);
    text-decoration: none;
}

.sa-panel__footer-link:hover {
    text-decoration: underline;
}

.sa-table__link {
    color: rgba(var(--sa-accent),0.9);
    text-decoration: none;
    font-weight: 600;
}

.sa-table__link:hover {
    text-decoration: underline;
}

/* ── Tables ──────────────────────────────────────────────────────────────────── */

.sa-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.82rem;
}

.sa-table th {
    text-align: left;
    font-size: 0.65rem;
    font-weight: 700;
    letter-spacing: 0.07em;
    text-transform: uppercase;
    color: rgba(var(--sa-text-dim),0.6);
    padding: 0 8px 8px 0;
    border-bottom: 1px solid rgba(255,255,255,0.06);
}

.sa-table td {
    padding: 7px 8px 7px 0;
    color: rgba(var(--sa-text),0.88);
    border-bottom: 1px solid rgba(255,255,255,0.04);
    vertical-align: middle;
}

.sa-table tbody tr:last-child td { border-bottom: none; }

.sa-table tbody tr {
    transition: background 0.1s ease;
}
.sa-table tbody tr:hover td {
    background: rgba(255,255,255,0.025);
}

.sa-table__num {
    text-align: right !important;
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
    color: rgba(var(--sa-text),0.75);
}

.sa-table__path {
    max-width: 200px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-family: "SF Mono","Fira Code","Cascadia Code",monospace;
    font-size: 0.77rem;
    color: rgba(180,210,180,0.85);
}

.sa-table__bar {
    width: 72px;
    padding-left: 10px !important;
}

/* ── Table pager ─────────────────────────────────────────────────────────────── */

.sa-pager {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
    margin-top: 10px;
}

.sa-pager__label {
    font-size: 0.78rem;
    color: rgba(var(--sa-text-muted),0.75);
    white-space: nowrap;
}

/* ── Mini bar ────────────────────────────────────────────────────────────────── */

.sa-mini-bar {
    height: 5px;
    border-radius: 3px;
    background: rgba(255,255,255,0.05);
    overflow: hidden;
}

.sa-mini-bar__fill {
    height: 100%;
    border-radius: 3px;
    transition: width 0.3s ease;
}

/* ── Consent + device bars ───────────────────────────────────────────────────── */

.sa-consent-list {
    display: flex;
    flex-direction: column;
    gap: 9px;
}

.sa-consent-row {
    display: grid;
    grid-template-columns: max-content 1fr 32px;
    align-items: center;
    gap: 10px;
}

.sa-consent-row__label {
    font-size: 0.78rem;
    color: rgba(185,185,185,0.85);
    white-space: nowrap;
}

.sa-consent-row__pct {
    font-size: 0.75rem;
    font-weight: 600;
    color: rgba(var(--sa-text),0.7);
    text-align: right;
    font-variant-numeric: tabular-nums;
}

.sa-bar {
    height: 8px;
    border-radius: 4px;
    background: rgba(255,255,255,0.05);
    overflow: hidden;
    display: flex;
}

.sa-bar__seg {
    height: 100%;
    transition: width 0.3s ease;
}

/* ── World map ───────────────────────────────────────────────────────────────── */

.sa-map {
    margin-bottom: 14px;
}

.sa-map__inner {
    width: 100%;
    height: 100%;
    min-height: 220px;
    border-radius: 8px;
    overflow: hidden;
    background: rgba(0,0,0,0.12);
    border: 1px solid rgba(255,255,255,0.05);
}

.sa-map__caption {
    margin: 6px 2px 0;
    font-size: 0.72rem;
    color: rgba(var(--sa-text-muted),0.65);
}

.sa-map--empty {
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 160px;
    font-size: 0.875rem;
    color: rgba(var(--sa-text-dim),0.6);
    background: rgba(0,0,0,0.1);
    border: 1px solid rgba(255,255,255,0.05);
    border-radius: 8px;
}

/* ── Copy button ─────────────────────────────────────────────────────────────── */

.sa-copy-btn {
    padding: 5px 13px;
    border-radius: 8px;
    border: 1px solid rgba(255,255,255,0.12);
    background: rgba(255,255,255,0.05);
    color: rgba(var(--sa-text),0.9);
    font-size: 0.8rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s, border-color 0.15s;
    white-space: nowrap;
}

.sa-copy-btn:hover { background: rgba(255,255,255,0.09); border-color: rgba(255,255,255,0.2); }
.sa-copy-btn--done { background: rgba(74,222,128,0.12); border-color: rgba(74,222,128,0.3); color: #6ee7a0; }

/* ── Setup / empty state card ────────────────────────────────────────────────── */

.sa-setup {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    gap: 16px;
    padding: 56px 32px;
    border-radius: 16px;
    border: 1px dashed rgba(255,255,255,0.1);
    background: rgba(0,0,0,0.1);
}

.sa-setup__icon { color: rgba(var(--sa-accent),0.8); }

.sa-setup__icon svg {
    width: 36px;
    height: 36px;
}

.sa-setup__title {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 600;
    color: #ececec;
}

.sa-setup__body {
    margin: 0;
    max-width: 520px;
    font-size: 0.9rem;
    line-height: 1.65;
    color: rgba(175,175,175,0.85);
}

.sa-setup__loading {
    margin: 0;
    font-size: 0.875rem;
    color: rgba(var(--sa-text-muted),0.65);
}

.sa-setup__gen-btn {
    display: inline-flex;
    align-items: center;
    padding: 10px 24px;
    border-radius: 10px;
    border: 1px solid rgba(var(--sa-accent),0.45);
    background: rgba(var(--sa-accent),0.1);
    color: rgba(227,200,130,0.95);
    font-size: 0.9rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.2s, border-color 0.2s;
}

.sa-setup__gen-btn:hover:not(:disabled) {
    background: rgba(var(--sa-accent),0.2);
    border-color: rgba(var(--sa-accent),0.65);
}

.sa-setup__gen-btn:disabled { opacity: 0.45; cursor: not-allowed; }

.sa-setup__snippet-wrap {
    width: 100%;
    max-width: 640px;
    text-align: left;
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.sa-setup__snippet-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.sa-setup__snippet-label {
    font-size: 0.7rem;
    font-weight: 700;
    letter-spacing: 0.07em;
    text-transform: uppercase;
    color: rgba(var(--sa-accent),0.8);
}

.sa-setup__snippet {
    margin: 0;
    padding: 14px 16px;
    border-radius: 10px;
    border: 1px solid rgba(255,255,255,0.07);
    background: rgba(0,0,0,0.28);
    font-family: "SF Mono","Fira Code","Cascadia Code",monospace;
    font-size: 0.78rem;
    line-height: 1.7;
    color: #c9e9a0;
    white-space: pre-wrap;
    word-break: break-all;
}

.sa-setup__hint {
    margin: 0;
    font-size: 0.78rem;
    color: rgba(var(--sa-text-dim),0.65);
    line-height: 1.5;
}

.sa-setup__hint code {
    font-family: "SF Mono","Fira Code","Cascadia Code",monospace;
    font-size: 0.82em;
    background: rgba(255,255,255,0.07);
    border-radius: 4px;
    padding: 1px 5px;
    color: #d4b896;
}

/* ── Overview bento layout ────────────────────────────────────────────────────── */

.sa-overview {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

/* KPI strip — equal-width cards, expands to 6 when quality-leads is present */
.sa-kpi-strip-wrap {
    position: relative;
}
.sa-kpi-strip {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 12px;
}
.sa-kpi-strip--4 {
    grid-template-columns: repeat(4, 1fr);
}
.sa-kpi-strip--6 {
    grid-template-columns: repeat(6, 1fr);
}

.sa-customize-btn {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    margin-top: 8px;
    padding: 4px 10px;
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 6px;
    background: transparent;
    color: rgba(180,180,200,0.6);
    font-size: 0.72rem;
    cursor: pointer;
    transition: color 0.15s, border-color 0.15s;
}
.sa-customize-btn:hover {
    color: rgba(200,200,220,0.9);
    border-color: rgba(255,255,255,0.2);
}

.sa-customize-backdrop {
    position: fixed;
    inset: 0;
    z-index: 200;
    background: rgba(0,0,0,0.45);
    display: flex;
    align-items: flex-start;
    justify-content: center;
    padding-top: 120px;
}
.sa-customize-panel {
    background: #1e1e2e;
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 12px;
    width: 340px;
    padding: 20px;
    box-shadow: 0 20px 60px rgba(0,0,0,0.6);
}
.sa-customize-panel__head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 6px;
}
.sa-customize-panel__title {
    font-size: 0.9rem;
    font-weight: 600;
    color: rgba(220,220,240,0.95);
}
.sa-customize-panel__close {
    background: none;
    border: none;
    color: rgba(180,180,200,0.5);
    font-size: 0.85rem;
    cursor: pointer;
    padding: 2px 6px;
    border-radius: 4px;
}
.sa-customize-panel__close:hover { color: rgba(220,220,240,0.9); }
.sa-customize-panel__sub {
    font-size: 0.75rem;
    color: rgba(150,150,175,0.6);
    margin: 0 0 14px;
}
.sa-customize-panel__list {
    display: flex;
    flex-direction: column;
    gap: 4px;
    margin-bottom: 16px;
}
.sa-customize-panel__item {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 8px 10px;
    border-radius: 8px;
    cursor: pointer;
    border: 1px solid transparent;
    transition: background 0.12s, border-color 0.12s;
}
.sa-customize-panel__item:hover {
    background: rgba(255,255,255,0.04);
}
.sa-customize-panel__item--on {
    background: rgba(96,165,250,0.07);
    border-color: rgba(96,165,250,0.2);
}
.sa-customize-panel__check {
    width: 15px;
    height: 15px;
    flex-shrink: 0;
    accent-color: rgba(96,165,250,0.9);
    cursor: pointer;
}
.sa-customize-panel__item-label {
    font-size: 0.82rem;
    font-weight: 500;
    color: rgba(210,210,230,0.9);
    flex: 1;
}
.sa-customize-panel__item-desc {
    font-size: 0.72rem;
    color: rgba(140,140,165,0.55);
}
.sa-customize-panel__actions {
    display: flex;
    gap: 8px;
    justify-content: flex-end;
}
.sa-customize-panel__reset {
    padding: 6px 12px;
    border-radius: 6px;
    border: 1px solid rgba(255,255,255,0.1);
    background: transparent;
    color: rgba(160,160,185,0.7);
    font-size: 0.78rem;
    cursor: pointer;
}
.sa-customize-panel__reset:hover { color: rgba(200,200,220,0.9); }
.sa-customize-panel__apply {
    padding: 6px 14px;
    border-radius: 6px;
    border: none;
    background: rgba(96,165,250,0.85);
    color: #fff;
    font-size: 0.78rem;
    font-weight: 600;
    cursor: pointer;
}
.sa-customize-panel__apply:hover { background: rgba(96,165,250,1); }

/* Row 1: main chart (60 %) + live feed (40 %) */
.sa-overview-main {
    display: grid;
    grid-template-columns: 3fr 2fr;
    gap: 12px;
    align-items: start;
}

/* Row 2: world-map (wide) | top countries | devices */
.sa-overview-geo {
    display: grid;
    grid-template-columns: 2.2fr 2fr 1.5fr;
    gap: 12px;
    align-items: start;
}

/* Row 3: traffic sources | top pages */
.sa-overview-bottom {
    display: grid;
    grid-template-columns: 5fr 4fr;
    gap: 12px;
    align-items: start;
}

@media (max-width: 1200px) {
    .sa-kpi-strip    { grid-template-columns: repeat(3, 1fr); }
    .sa-kpi-strip--4 { grid-template-columns: repeat(2, 1fr); }
    .sa-kpi-strip--6 { grid-template-columns: repeat(3, 1fr); }
    .sa-overview-geo { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 900px) {
    .sa-overview-main   { grid-template-columns: 1fr; }
    .sa-overview-bottom { grid-template-columns: 1fr; }
}

@media (max-width: 680px) {
    .sa-kpi-strip, .sa-kpi-strip--4, .sa-kpi-strip--6 { grid-template-columns: repeat(2, 1fr); }
    .sa-overview-geo { grid-template-columns: 1fr; }
}

/* ── Audience sub-page grid ──────────────────────────────────────────────────── */

.sa-audience-grid {
    display: grid;
    gap: 12px;
    align-items: start;
    grid-template-columns: repeat(2, 1fr);
    grid-template-areas:
        "kpis       kpis"
        "nvr        nvr"
        "interests  interests"
        "countries  countries"
        "browsers   os"
        "screens    devices"
        "lang       tz";
}

.sa-aud-kpis      { grid-area: kpis;      display: flex; gap: 12px; flex-wrap: wrap; }
.sa-aud-kpis .sa-kpi { flex: 1 1 200px; }
.sa-aud-nvr       { grid-area: nvr;       }
.sa-aud-interests  { grid-area: interests; }
.sa-aud-countries { grid-area: countries; }
.sa-aud-browsers  { grid-area: browsers;  }
.sa-aud-os        { grid-area: os;        }
.sa-aud-devices   { grid-area: devices;   }
.sa-aud-screens   { grid-area: screens;   }
.sa-aud-lang      { grid-area: lang;      }
.sa-aud-tz        { grid-area: tz;        }

/* ── Interest rule rows (engagement-scored on/off-topic split) ───────────── */

.sa-int-rules-list {
    display: flex;
    flex-direction: column;
}

.sa-int-rule-row {
    display: flex;
    flex-direction: column;
    gap: 6px;
    padding: 11px 0;
    border-bottom: 1px solid rgba(255,255,255,0.05);
}
.sa-int-rule-row:last-of-type { border-bottom: none; }

.sa-int-rule-row__header {
    display: flex;
    align-items: center;
    gap: 8px;
}
.sa-int-rule-row__label {
    font-size: 0.88rem;
    font-weight: 600;
    color: rgba(220,230,245,0.9);
    flex: 1;
    min-width: 0;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.sa-int-rule-row__stats {
    display: flex;
    align-items: center;
    gap: 7px;
    font-size: 0.78rem;
    color: rgba(180,180,200,0.5);
    flex-shrink: 0;
}
.sa-int-rule-row__score {
    font-weight: 600;
    font-variant-numeric: tabular-nums;
}

.sa-int-rule-row__bar {
    height: 8px;
    background: rgba(255,255,255,0.06);
    border-radius: 4px;
    overflow: hidden;
}
.sa-int-rule-row__bar-on {
    height: 100%;
    background: rgba(16,185,129,0.55);
    border-radius: 4px;
    transition: width 0.4s ease;
    min-width: 2px;
}

.sa-int-rule-row__legend {
    display: flex;
    gap: 14px;
    font-size: 0.75rem;
    font-variant-numeric: tabular-nums;
}
.sa-int-rule-row__on  { color: rgba(16,185,129,0.75); }
.sa-int-rule-row__off { color: rgba(180,180,200,0.38); }

/* ── Skeleton / shimmer loader ─────────────────────────────────────────────── */
@keyframes sa-shimmer {
    0%   { background-position: -200% 0; }
    100% { background-position:  200% 0; }
}
.sa-skeleton {
    border-radius: 4px;
    background: linear-gradient(
        90deg,
        rgba(255,255,255,0.04) 25%,
        rgba(255,255,255,0.09) 50%,
        rgba(255,255,255,0.04) 75%
    );
    background-size: 200% 100%;
    animation: sa-shimmer 1.5s ease-in-out infinite;
    flex-shrink: 0;
}
.sa-skeleton-rows {
    display: flex;
    flex-direction: column;
    gap: 12px;
    padding: 4px 0;
}
.sa-skeleton-row {
    display: flex;
    align-items: center;
    gap: 10px;
}

/* ── Shared dark-theme form primitives (interest rules, etc.) ──────────────── */

.ia-input {
    background: rgba(255,255,255,0.05);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 6px;
    color: rgba(220,230,245,0.9);
    font-size: 0.83rem;
    padding: 7px 10px;
    width: 100%;
    outline: none;
    box-sizing: border-box;
    transition: border-color 0.15s;
}
.ia-input::placeholder {
    color: rgba(180,180,200,0.35);
}
.ia-input:focus {
    border-color: rgba(var(--sa-accent),0.5);
}

.ia-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border: none;
    border-radius: 6px;
    font-size: 0.82rem;
    font-weight: 600;
    padding: 7px 14px;
    cursor: pointer;
    white-space: nowrap;
    transition: opacity 0.15s;
}
.ia-btn:disabled {
    opacity: 0.45;
    cursor: not-allowed;
}
.ia-btn--primary {
    background: rgba(var(--sa-accent),0.7);
    color: #111118;
}
.ia-btn--primary:not(:disabled):hover {
    background: rgba(var(--sa-accent),0.9);
}

.sa-interest-form {
    display: grid;
    grid-template-columns: 1fr 1fr auto auto;
    gap: 10px;
    align-items: end;
    margin-top: 4px;
}

@media (max-width: 700px) {
    .sa-interest-form {
        grid-template-columns: 1fr 1fr;
    }
}

/* ── Error boundary inline card ──────────────────────────────────────────── */

.sa-boundary-error {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 10px 14px;
    border-radius: 6px;
    background: rgba(239,68,68,0.08);
    border: 1px solid rgba(239,68,68,0.2);
    color: rgba(252,165,165,0.85);
    font-size: 13px;
}
.sa-boundary-error__icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 18px;
    height: 18px;
    border-radius: 50%;
    background: rgba(239,68,68,0.25);
    color: rgba(252,165,165,0.9);
    font-size: 11px;
    font-weight: 700;
    flex-shrink: 0;
}

.sa-aud-nvr-bars { display: flex; gap: 8px; }
.sa-aud-nvr-bars > div { flex: 1; }

@media (max-width: 620px) {
    .sa-audience-grid {
        grid-template-columns: 1fr;
        grid-template-areas:
            "kpis" "nvr" "interests" "countries" "browsers" "os"
            "devices" "screens" "lang" "tz";
    }
    .sa-aud-nvr-bars { flex-direction: column; }
    .sa-int-rule-row__stats { gap: 5px; font-size: 0.72rem; }
}

/* ── User flow diagram ────────────────────────────────────────────────────────── */

.sa-flow-scroll {
    overflow-x: auto;
    overflow-y: hidden;
    padding-bottom: 4px;
}

.sa-flow-controls {
    display: flex;
    align-items: center;
    gap: 12px;
    flex-wrap: wrap;
    margin-bottom: 14px;
}

.sa-flow-tabs {
    display: flex;
    gap: 4px;
    background: rgba(255, 255, 255, 0.04);
    border-radius: 8px;
    padding: 3px;
}

.sa-flow-tab {
    background: transparent;
    border: none;
    color: rgba(var(--sa-text-secondary),0.7);
    font-size: 0.76rem;
    padding: 6px 12px;
    border-radius: 6px;
    cursor: pointer;
}

.sa-flow-tab.--active {
    background: rgba(var(--sa-accent), 0.18);
    color: rgba(230, 210, 160, 0.95);
}

.sa-flow-clear {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    margin-bottom: 10px;
    padding: 5px 12px;
    background: rgba(var(--sa-accent), 0.14);
    border: 1px solid rgba(var(--sa-accent), 0.35);
    border-radius: 999px;
    color: rgba(230, 210, 160, 0.95);
    font-size: 0.75rem;
    font-weight: 600;
    cursor: pointer;
}

.sa-flow-clear:hover {
    background: rgba(var(--sa-accent), 0.22);
}

.sa-flow-trace-loading {
    display: inline-block;
    margin-bottom: 10px;
    margin-left: 8px;
    font-size: 0.75rem;
    color: rgba(var(--sa-text-secondary),0.6);
}

/* ── Google Analytics sub-page stack ─────────────────────────────────────────── */

.sa-ga4-stack {
    display: flex;
    flex-direction: column;
    gap: 14px;
}

.ga4-two-col {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 14px;
}

@media (max-width: 700px) {
    .ga4-two-col { grid-template-columns: 1fr; }
}

/* New vs Returning */
.ga4-nvr {
    display: flex;
    flex-direction: column;
    gap: 10px;
}
.ga4-nvr__bar-track {
    display: flex;
    height: 8px;
    border-radius: 4px;
    overflow: hidden;
    background: rgba(255,255,255,0.05);
}
.ga4-nvr__bar-new {
    background: rgba(96,165,250,0.55);
    border-radius: 4px 0 0 4px;
    transition: width 0.4s ease;
}
.ga4-nvr__bar-ret {
    background: rgba(52,211,153,0.45);
    border-radius: 0 4px 4px 0;
    transition: width 0.4s ease;
}
.ga4-nvr__legend {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 0.78rem;
    color: rgba(var(--sa-text-muted),0.7);
}
.ga4-nvr__dot {
    width: 8px; height: 8px;
    border-radius: 50%;
    flex-shrink: 0;
}
.ga4-nvr__dot--new { background: rgba(96,165,250,0.7); }
.ga4-nvr__dot--ret { background: rgba(52,211,153,0.6); }
.ga4-nvr__label strong { color: rgba(210,215,230,0.9); }
.ga4-nvr__label { margin-right: 8px; }

/* Channel table inline bar */
.ga4-ch-bar-cell {
    display: flex;
    align-items: center;
    gap: 8px;
    min-width: 140px;
}
.ga4-ch-bar-track {
    flex: 1;
    height: 5px;
    background: rgba(255,255,255,0.05);
    border-radius: 3px;
    overflow: hidden;
}
.ga4-ch-bar-fill {
    height: 100%;
    background: rgba(145,158,180,0.35);
    border-radius: 3px;
    transition: width 0.3s ease;
}
.ga4-ch-bar-pct {
    font-size: 0.72rem;
    color: rgba(145,158,180,0.55);
    white-space: nowrap;
    min-width: 36px;
    text-align: right;
}

/* ── Search Console sub-page stack ───────────────────────────────────────────── */

.sa-gsc-stack {
    display: flex;
    flex-direction: column;
    gap: 14px;
}

/* Generic KPI row — a flat strip of KpiCards, for pages (Search Console,
   Audience, Acquisition) that don't need a named-grid-area layout. */
.sa-kpi-row {
    display: flex;
    gap: 12px;
    flex-wrap: wrap;
}

.sa-kpi-row .sa-kpi {
    flex: 1 1 200px;
}

/* ── Acquisition sub-page grid ───────────────────────────────────────────────── */

.sa-acq-grid {
    display: grid;
    gap: 12px;
    align-items: start;
    grid-template-columns: repeat(2, 1fr);
    grid-template-areas:
        "kpis      kpis"
        "pages     utm"
        "referrers hosts";
}

.sa-acq-kpis      { grid-area: kpis; display: flex; gap: 12px; flex-wrap: wrap; }
.sa-acq-kpis .sa-kpi { flex: 1 1 200px; }
.sa-acq-pages     { grid-area: pages;     }
.sa-acq-utm       { grid-area: utm;       }
.sa-acq-referrers { grid-area: referrers; }
.sa-acq-hosts     { grid-area: hosts;     }

@media (max-width: 760px) {
    .sa-acq-grid {
        grid-template-columns: 1fr;
        grid-template-areas: "kpis" "pages" "utm" "referrers" "hosts";
    }
}

/* ── Ad Spend sub-page grid ──────────────────────────────────────────────────── */

.sa-as-grid {
    display: grid;
    gap: 12px;
    align-items: start;
    grid-template-columns: repeat(3, 1fr);
    grid-template-areas:
        "kpi0      kpi1      kpi2"
        "chart     chart     chart"
        "platforms platforms platforms"
        "domains   domains   domains";
}

.sa-as-kpi0      { grid-area: kpi0; }
.sa-as-kpi1      { grid-area: kpi1; }
.sa-as-kpi2      { grid-area: kpi2; }
.sa-as-chart     { grid-area: chart; align-self: start; }
.sa-as-platforms { grid-area: platforms; }
.sa-as-domains   { grid-area: domains; }

@media (max-width: 760px) {
    .sa-as-grid {
        grid-template-columns: 1fr;
        grid-template-areas: "kpi0" "kpi1" "kpi2" "chart" "platforms" "domains";
    }
}

.sa-channel-cards {
    display: grid;
    gap: 14px;
    grid-template-columns: repeat(auto-fit, minmax(420px, 1fr));
    margin-top: 12px;
}

.sa-channel-card {
    background: rgba(255,255,255,0.03);
    border: 1px solid rgba(255,255,255,0.06);
    border-radius: 10px;
    padding: 12px 14px 14px;
}

.sa-channel-card__title {
    margin: 0 0 10px;
    font-size: 0.8rem;
    font-weight: 600;
    color: rgba(var(--sa-text),0.85);
}

.sa-channel-card__tiles {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 6px;
    margin-bottom: 10px;
}

.sa-channel-tile {
    display: flex;
    flex-direction: column;
    gap: 2px;
    padding: 8px 10px;
    border-radius: 8px;
    border: none;
    background: rgba(255,255,255,0.05);
    cursor: pointer;
    text-align: left;
    font: inherit;
}

.sa-channel-tile--active {
    box-shadow: 0 0 0 1px rgba(255,255,255,0.15) inset;
}

.sa-channel-tile--active .sa-channel-tile__label,
.sa-channel-tile--active .sa-channel-tile__value {
    color: #fff;
}

.sa-channel-tile--static {
    cursor: default;
}

.sa-channel-tile__label {
    font-size: 0.62rem;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: rgba(var(--sa-text-secondary),0.7);
}

.sa-channel-tile__value {
    font-size: 0.95rem;
    font-weight: 700;
    color: rgba(230,230,230,0.92);
}

@media (max-width: 620px) {
    .sa-channel-card__tiles {
        grid-template-columns: repeat(2, 1fr);
    }
}

/* ── Consent sub-page grid ───────────────────────────────────────────────────── */

.sa-consent-page-grid {
    display: grid;
    gap: 12px;
    align-items: start;
    grid-template-columns: repeat(4, 1fr);
    grid-template-areas:
        "kpi1 kpi2 kpi3 kpi4"
        "bars bars bars bars";
}

.sa-cg-kpi1 { grid-area: kpi1; }
.sa-cg-kpi2 { grid-area: kpi2; }
.sa-cg-kpi3 { grid-area: kpi3; }
.sa-cg-kpi4 { grid-area: kpi4; }
.sa-cg-bars { grid-area: bars; }

@media (max-width: 1100px) {
    .sa-consent-page-grid {
        grid-template-columns: repeat(2, 1fr);
        grid-template-areas:
            "kpi1 kpi2"
            "kpi3 kpi4"
            "bars bars";
    }
}

@media (max-width: 620px) {
    .sa-consent-page-grid {
        grid-template-columns: 1fr;
        grid-template-areas:
            "kpi1" "kpi2" "kpi3" "kpi4" "bars";
    }
}

/* ── Heatmap sub-page grid ───────────────────────────────────────────────────── */

/* Screenshot is the hero — fixed 340 px sidebar holds data panels;
   viewport takes all remaining width. */
.sa-heatmap-grid {
    display: grid;
    gap: 12px;
    align-items: start;
    grid-template-columns: 1fr 340px;
    grid-template-areas:
        "controls controls"
        "viewport sidecar";
}

.sa-heatmap__controls {
    grid-area: controls;
    display: flex;
    align-items: center;
    gap: 12px;
    flex-wrap: wrap;
}

/* Path selector stretches to fill available space in the controls row */
.sa-heatmap__path-select { flex: 1; min-width: 180px; }

/* ── Viewport — the hero screenshot area ── */
.sa-heatmap__viewport {
    grid-area: viewport;
    display: flex;
    flex-direction: column;
    border-radius: 12px;
    overflow: hidden;
    background: rgba(0,0,0,0.22);
    border: 1px solid rgba(255,255,255,0.07);
    /* Always fill most of the screen so the screenshot is the main attraction */
    min-height: calc(100vh - 210px);
}

/* Thin amber label strip — replaces the heavy panel h3 */
.sa-heatmap__viewport-label {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 11px 16px;
    font-size: 0.78rem;
    font-weight: 500;
    color: rgba(var(--sa-accent),0.85);
    border-bottom: 1px solid rgba(255,255,255,0.06);
    flex-shrink: 0;
}

/* ── Data sidebar ── */
.sa-heatmap__sidecar {
    grid-area: sidecar;
    display: flex;
    flex-direction: column;
    gap: 12px;
}

/* ≤ 1500px — covers all 13" MacBook variants (1280–1470 px logical).
   Viewport is full-width hero; sidecar panels sit side-by-side below. */
@media (max-width: 1500px) {
    .sa-heatmap-grid {
        grid-template-columns: 1fr;
        grid-template-areas:
            "controls"
            "viewport"
            "sidecar";
    }
    .sa-heatmap__sidecar { flex-direction: row; }
    .sa-heatmap__sidecar > .sa-panel { flex: 1; min-width: 0; }
}

@media (max-width: 900px) {
    .sa-heatmap__sidecar { flex-direction: column; }
    .sa-heatmap__sidecar > .sa-panel { flex: none; }
}

.sa-select {
    background: rgba(255,255,255,0.05);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 8px;
    color: rgba(var(--sa-text),0.9);
    font-size: 0.82rem;
    padding: 7px 10px;
    min-width: 220px;
}

.sa-heatmap__device-tabs {
    display: flex;
    gap: 4px;
    background: rgba(255,255,255,0.04);
    border-radius: 8px;
    padding: 3px;
}

.sa-heatmap__device-tab {
    background: transparent;
    border: none;
    color: rgba(var(--sa-text-secondary),0.7);
    font-size: 0.76rem;
    padding: 6px 12px;
    border-radius: 6px;
    cursor: pointer;
}

.sa-heatmap__device-tab.--active {
    background: rgba(var(--sa-accent),0.18);
    color: rgba(230,210,160,0.95);
}

/* frame-outer fills the viewport panel via flex: 1; the parent's min-height
   is the floor. min-height: 0 overrides the browser default so flexbox can
   actually shrink it when the viewport panel is smaller than the screenshot. */
.sa-heatmap__frame-outer {
    flex: 1;
    min-height: 0;
    width: 100%;
    overflow-y: auto;
    overflow-x: hidden;
    scrollbar-width: thin;
    scrollbar-color: rgba(var(--sa-accent),0.35) rgba(0,0,0,0.18);
}
.sa-heatmap__frame-outer::-webkit-scrollbar       { width: 5px; }
.sa-heatmap__frame-outer::-webkit-scrollbar-track { background: rgba(0,0,0,0.18); }
.sa-heatmap__frame-outer::-webkit-scrollbar-thumb { background: rgba(var(--sa-accent),0.35); border-radius: 3px; }

/* Positioning context for the SVG overlay — no overflow: hidden so the
   scroll container (frame-outer) handles clipping. */
.sa-heatmap__frame-wrap {
    position: relative;
    width: 100%;
}

.sa-heatmap__frame-img {
    display: block;
    width: 100%;
    height: auto;
    pointer-events: none;
    user-select: none;
}

.sa-heatmap__frame-fallback {
    flex: 1;
    min-height: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    padding: 24px;
    font-size: 0.8rem;
    color: rgba(var(--sa-text-muted),0.6);
}
.sa-heatmap__frame-fallback.--error { color: #f5aeae; }

/* Height is injected via inline style (JS calculates rendered image height)
   so the viewBox maps precisely to the full image, not just the visible area. */
.sa-heatmap__overlay {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    pointer-events: none;
}

.sa-scroll-funnel {
    display: flex;
    flex-direction: column;
    gap: 9px;
}

/* ── Recording player ────────────────────────────────────────────────────────── */

.sa-recording-player {
    width: 100%;
    min-height: 520px;
    display: flex;
    justify-content: center;
}

/* ── Bots sub-page grid ──────────────────────────────────────────────────────── */

.sa-bots-grid {
    display: grid;
    gap: 12px;
    align-items: start;
    grid-template-columns: repeat(4, 1fr);
    grid-template-areas:
        "kpi1  kpi2  category   category"
        "list  list  list       list"
        "asns  asns  suspicious suspicious"
        "pages pages recent     recent";
}

.sa-bots-kpi1       { grid-area: kpi1;       }
.sa-bots-kpi2       { grid-area: kpi2;       }
.sa-bots-category   { grid-area: category;   }
.sa-bots-list       { grid-area: list;       }
.sa-bots-asns       { grid-area: asns;       }
.sa-bots-suspicious { grid-area: suspicious; }
.sa-bots-pages      { grid-area: pages;      }
.sa-bots-recent     { grid-area: recent;     }

@media (max-width: 1100px) {
    .sa-bots-grid {
        grid-template-columns: repeat(2, 1fr);
        grid-template-areas:
            "kpi1       kpi2"
            "category   category"
            "list       list"
            "asns       suspicious"
            "pages      pages"
            "recent     recent";
    }
}

@media (max-width: 620px) {
    .sa-bots-grid {
        grid-template-columns: 1fr;
        grid-template-areas:
            "kpi1" "kpi2" "category" "list" "asns" "suspicious" "pages" "recent";
    }
}

/* ── Conversions section (ConversionsPanel, embedded on the Overview page) ───── */

.sa-section {
    background: rgba(26,26,30,0.75);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 14px;
    padding: 18px 20px;
    box-shadow: 0 2px 12px rgba(0,0,0,0.18);
}

.sa-panel__head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 14px;
}

.sa-section__title {
    margin: 0;
    font-size: 0.72rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: rgba(var(--sa-text-muted),0.65);
    display: flex;
    align-items: center;
    gap: 8px;
}

.sa-panel__sub {
    color: rgba(var(--sa-text-dim),0.55);
    font-size: 0.82rem;
    margin: 0;
}

.sa-add-event-btn {
    display: flex;
    align-items: center;
    gap: 6px;
    background: rgba(var(--sa-accent),0.12);
    border: 1px solid rgba(var(--sa-accent),0.3);
    color: rgba(230,210,160,0.95);
    font-size: 0.78rem;
    font-weight: 600;
    padding: 7px 12px;
    border-radius: 8px;
    cursor: pointer;
}

.sa-add-event-btn:hover {
    background: rgba(var(--sa-accent),0.2);
}

.sa-event-form {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    padding: 14px;
    margin-bottom: 14px;
    background: rgba(255,255,255,0.03);
    border: 1px solid rgba(255,255,255,0.07);
    border-radius: 10px;
}

.sa-event-form__input,
.sa-event-form__select {
    background: rgba(255,255,255,0.05);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 8px;
    color: rgba(var(--sa-text),0.9);
    font-size: 0.82rem;
    padding: 7px 10px;
}

.sa-event-form__input {
    flex: 1;
    min-width: 160px;
}

.sa-event-form__submit {
    background: rgba(var(--sa-accent),0.55);
    border: none;
    color: #1a1a1e;
    font-weight: 600;
    font-size: 0.82rem;
    padding: 7px 16px;
    border-radius: 8px;
    cursor: pointer;
}

.sa-event-form__submit:disabled { opacity: 0.5; cursor: not-allowed; }

.sa-event-form__hint {
    flex-basis: 100%;
    margin: 2px 0 0;
    font-size: 0.76rem;
    color: rgba(var(--sa-accent),0.85);
}

.sa-events-list {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.sa-event-row {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    padding: 12px 4px;
    border-bottom: 1px solid rgba(255,255,255,0.05);
}

.sa-event-row:last-child { border-bottom: none; }

.sa-event-row__icon {
    color: rgba(var(--sa-accent),0.8);
    flex-shrink: 0;
    margin-top: 2px;
}

.sa-event-row__icon svg { width: 18px; height: 18px; }

.sa-event-row__body { flex: 1; min-width: 0; }

.sa-event-row__top {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
}

.sa-event-row__name {
    font-size: 0.88rem;
    font-weight: 600;
    color: rgba(var(--sa-text),0.92);
}

.sa-event-row__kind {
    font-size: 0.62rem;
    font-weight: 700;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: rgba(var(--sa-text-muted),0.65);
    background: rgba(255,255,255,0.05);
    padding: 2px 6px;
    border-radius: 4px;
}

.sa-event-row__unregistered {
    font-size: 0.68rem;
    color: rgba(220,160,60,0.85);
}

.sa-event-row__stats {
    display: flex;
    gap: 14px;
    margin-top: 4px;
    font-size: 0.78rem;
    color: rgba(var(--sa-text-secondary),0.75);
    font-variant-numeric: tabular-nums;
}

.sa-event-row__consent-note {
    color: rgba(var(--sa-text-dim),0.55);
}

.sa-event-row__toggles {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 6px;
    margin-left: -8px;
}

.sa-event-row__snippet-toggle {
    background: none;
    border: none;
    color: rgba(150,180,220,0.75);
    font-size: 0.72rem;
    padding: 6px 8px;
    min-height: 32px;
    border-radius: 4px;
    cursor: pointer;
}

.sa-event-row__snippet-toggle:hover { background: rgba(255,255,255,0.06); }

.sa-event-row__snippet {
    margin-top: 6px;
    padding: 8px 10px;
    background: rgba(0,0,0,0.25);
    border-radius: 6px;
    font-family: "SF Mono","Fira Code","Cascadia Code",monospace;
    font-size: 0.74rem;
    color: rgba(180,210,180,0.85);
    overflow-x: auto;
}

.sa-event-row__payloads {
    margin-top: 8px;
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.sa-event-row__payloads-empty {
    font-size: 0.74rem;
    color: rgba(var(--sa-text-muted),0.65);
}

.sa-event-row__payload {
    padding: 8px 10px;
    background: rgba(0,0,0,0.25);
    border-radius: 6px;
}

.sa-event-row__payload-meta {
    display: flex;
    gap: 10px;
    font-size: 0.68rem;
    color: rgba(var(--sa-text-muted),0.7);
    font-variant-numeric: tabular-nums;
    margin-bottom: 4px;
}

.sa-event-row__payload-path {
    color: rgba(150,180,220,0.75);
    overflow-wrap: anywhere;
}

.sa-event-row__payload-data {
    margin: 0;
    font-family: "SF Mono","Fira Code","Cascadia Code",monospace;
    font-size: 0.74rem;
    color: rgba(180,210,180,0.85);
    overflow-x: auto;
}

.sa-event-row__delete {
    background: none;
    border: none;
    color: rgba(200,120,120,0.6);
    cursor: pointer;
    padding: 4px;
    flex-shrink: 0;
}

.sa-event-row__delete:hover { color: rgba(230,140,140,0.9); }
.sa-event-row__delete svg { width: 16px; height: 16px; }

/* ── Funnel builder ───────────────────────────────────────────────────────────── */

.sa-funnel-form { flex-direction: column; align-items: stretch; }

.sa-funnel-form__steps {
    display: flex;
    flex-direction: column;
    gap: 8px;
    width: 100%;
}

.sa-funnel-form__step {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
}

.sa-funnel-form__step-index {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 22px;
    height: 22px;
    flex-shrink: 0;
    border-radius: 50%;
    background: rgba(var(--sa-accent),0.16);
    color: rgba(230,210,160,0.95);
    font-size: 0.72rem;
    font-weight: 700;
}

.sa-funnel-form__step-actions {
    display: flex;
    gap: 4px;
    margin-left: auto;
}

.sa-funnel-form__step-actions button {
    background: none;
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 6px;
    color: rgba(var(--sa-text),0.8);
    font-size: 0.78rem;
    padding: 4px 7px;
    cursor: pointer;
}

.sa-funnel-form__step-actions button:hover:not(:disabled) { border-color: rgba(var(--sa-accent),0.4); color: rgba(230,210,160,0.95); }
.sa-funnel-form__step-actions button:disabled { opacity: 0.35; cursor: not-allowed; }
.sa-funnel-form__step-actions button svg { width: 14px; height: 14px; }

.sa-funnel-form__actions {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-top: 4px;
}

.sa-funnel-form__cancel {
    background: none;
    border: none;
    color: rgba(150,180,220,0.75);
    font-size: 0.8125rem;
    cursor: pointer;
    padding: 0;
}

.sa-funnel-form__cancel:hover { color: rgba(180,205,235,0.95); }

/* ── Quality leads KPI (only rendered once lead quality is configured) ───────── */

.sa-lead-kpi-wrap {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
}

.sa-lead-kpi-wrap > .sa-kpi {
    grid-column: span 1;
}

@media (max-width: 1100px) {
    .sa-lead-kpi-wrap { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 620px) {
    .sa-lead-kpi-wrap { grid-template-columns: 1fr; }
}

/* ── Conversions sub-page submenu (same visual language as the app's
   Settings sidebar — vertical list, gold inset-left-border active state —
   scoped to this page instead of the global fixed SideNav) ─────────────── */

.sa-conv-layout {
    display: flex;
    align-items: flex-start;
    gap: 24px;
}

.sa-conv-submenu {
    flex: 0 0 180px;
    position: sticky;
    top: 16px;
}

.sa-conv-submenu__list {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.sa-conv-submenu__item {
    margin: 0;
}

.sa-conv-submenu__link {
    display: block;
    width: 100%;
    text-align: left;
    appearance: none;
    border: none;
    background: transparent;
    color: rgba(var(--sa-text-muted),0.75);
    font-size: 0.82rem;
    font-weight: 600;
    padding: 9px 12px;
    border-radius: 6px;
    cursor: pointer;
}

.sa-conv-submenu__link:hover:not(.--active) {
    background-color: rgba(255,255,255,0.06);
    color: rgb(255,255,255);
}

.sa-conv-submenu__link.--active {
    background: rgba(255,255,255,0.08);
    color: rgb(255,255,255);
    box-shadow: inset 3px 0 0 0 rgb(var(--sa-accent));
}

.sa-conv-submenu-content {
    flex: 1;
    min-width: 0;
}

@media (max-width: 900px) {
    .sa-conv-layout {
        flex-direction: column;
        gap: 12px;
    }
    .sa-conv-submenu {
        flex: none;
        width: 100%;
        position: static;
    }
    .sa-conv-submenu__list {
        flex-direction: row;
        flex-wrap: wrap;
    }
    .sa-conv-submenu__link.--active {
        box-shadow: inset 0 -3px 0 0 rgb(var(--sa-accent));
    }
}

/* ── Conversions sub-page grid ────────────────────────────────────────────────── */

.sa-conv-grid {
    display: grid;
    gap: 12px;
    align-items: start;
}

.sa-conv-grid--overview {
    grid-template-columns: 1fr 1fr;
    grid-template-areas:
        "kpi1  kpi2"
        "trend trend"
        "map   map";
}

.sa-conv-grid--deepdive {
    grid-template-columns: 1fr 1fr;
    grid-template-areas:
        "ttc         channels"
        "funnel      funnel"
        "campaigns   campaigns";
}

.sa-conv-kpi1          { grid-area: kpi1;      }
.sa-conv-kpi2          { grid-area: kpi2;      }
.sa-conv-trend         { grid-area: trend;     }
.sa-conv-map           { grid-area: map;       }
.sa-conv-ttc           { grid-area: ttc;       }
.sa-conv-channels      { grid-area: channels;  }
.sa-conv-funnel-panel  { grid-area: funnel;    }
.sa-conv-campaigns     { grid-area: campaigns; }

@media (max-width: 900px) {
    .sa-conv-grid--overview {
        grid-template-columns: 1fr;
        grid-template-areas: "kpi1" "kpi2" "trend" "map";
    }
    .sa-conv-grid--deepdive {
        grid-template-columns: 1fr;
        grid-template-areas: "ttc" "channels" "funnel" "campaigns";
    }
}

.sa-map__mode-toggle {
    margin-left: auto;
    display: inline-flex;
    gap: 2px;
    padding: 2px;
    border-radius: 8px;
    background: rgba(255,255,255,0.04);
    border: 1px solid rgba(255,255,255,0.07);
}

.sa-map__mode-toggle button {
    appearance: none;
    border: none;
    background: transparent;
    color: rgba(var(--sa-text-muted),0.7);
    font-size: 0.66rem;
    font-weight: 700;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    padding: 4px 9px;
    border-radius: 6px;
    cursor: pointer;
}

.sa-map__mode-toggle button.is-active {
    background: rgba(var(--sa-accent),0.18);
    color: #e8d9b5;
}

/* ── Time-to-convert breakdown ──────────────────────────────────────────────── */

.sa-ttc-row {
    grid-template-columns: 90px 1fr 40px;
}

.sa-ttc-note {
    margin: 12px 0 0;
}

.sa-funnel-note {
    margin: 12px 0 0;
}

/* ── Checkout funnel ─────────────────────────────────────────────────────────── */

.sa-funnel-step {
    margin-top: 4px;
}

.sa-funnel-step__dropoff {
    font-size: 0.68rem;
    font-weight: 600;
    color: rgba(239,120,120,0.8);
    padding: 4px 0 4px 4px;
}

.sa-funnel-step__row {
    display: grid;
    grid-template-columns: 130px 1fr 90px;
    align-items: center;
    gap: 10px;
}

.sa-funnel-step__label {
    font-size: 0.8rem;
    color: rgba(var(--sa-text),0.9);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.sa-funnel-step__track {
    height: 22px;
    border-radius: 6px;
    background: rgba(255,255,255,0.05);
    overflow: hidden;
}

.sa-funnel-step__fill {
    height: 100%;
    min-width: 3px;
    border-radius: 6px;
    background: linear-gradient(90deg, rgba(var(--sa-accent),0.85), rgba(var(--sa-accent),0.55));
    transition: width 0.3s ease;
}

.sa-funnel-step__value {
    font-size: 0.8rem;
    font-weight: 600;
    color: rgba(var(--sa-text),0.85);
    text-align: right;
    font-variant-numeric: tabular-nums;
}

.sa-funnel-step__pct {
    font-weight: 500;
    color: rgba(var(--sa-text-muted),0.65);
    margin-left: 4px;
}

/* ── Campaign table (expandable rows) ───────────────────────────────────────── */

.sa-campaign-row {
    cursor: pointer;
}

.sa-campaign-row:hover td {
    background: rgba(255,255,255,0.02);
}

.sa-campaign-row--flat {
    cursor: default;
}

.sa-campaign-row--flat:hover td {
    background: transparent;
}

.sa-campaign-row__toggle {
    width: 20px;
    padding-right: 0 !important;
}

.sa-campaign-row__toggle .sa-icon {
    transition: transform 0.15s ease;
}

.sa-campaign-row__chevron--open {
    transform: rotate(-180deg);
}

.sa-campaign-row__detail td {
    border-bottom: 1px solid rgba(255,255,255,0.04);
    padding-top: 0;
    padding-bottom: 10px;
}

.sa-campaign-events {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
}

.sa-campaign-event-chip {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-size: 0.72rem;
    color: rgba(var(--sa-text-secondary),0.8);
    background: rgba(255,255,255,0.04);
    border: 1px solid rgba(255,255,255,0.07);
    border-radius: 999px;
    padding: 3px 10px 3px 12px;
}

.sa-campaign-event-chip b {
    color: #ececec;
    font-weight: 700;
}
/* ─── GA4 server-side badge ──────────────────────────────────────────────── */
.ga4-ss-badge {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    padding: 3px 10px;
    background: rgba(var(--sa-accent),0.12);
    border: 1px solid rgba(var(--sa-accent),0.3);
    border-radius: 20px;
    font-size: 0.71rem;
    font-weight: 600;
    color: rgba(var(--sa-accent),0.95);
    letter-spacing: 0.01em;
}

/* Platform breakdown */
.ga4-platform-breakdown {
    margin-top: 16px;
    padding-top: 14px;
    border-top: 1px solid rgba(255,255,255,0.06);
}
.ga4-platform-breakdown__title {
    margin: 0 0 10px;
    font-size: 0.72rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: rgba(145,158,180,0.65);
}
.ga4-platform-breakdown__rows {
    display: flex;
    flex-direction: column;
    gap: 7px;
}
.ga4-pb-row {
    display: grid;
    grid-template-columns: 160px 1fr 52px 70px;
    align-items: center;
    gap: 10px;
    font-size: 0.8rem;
}
.ga4-pb-row__name {
    color: rgba(185,195,215,0.85);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.ga4-pb-row--ss .ga4-pb-row__name {
    color: rgba(var(--sa-accent),0.9);
    font-weight: 600;
}
.ga4-pb-row__ss-icon {
    margin-right: 4px;
}
.ga4-pb-row__ss-hint {
    font-size: 0.7rem;
    font-weight: 400;
    color: rgba(140,145,200,0.65);
    margin-left: 4px;
}
.ga4-pb-row__bar-wrap {
    height: 8px;
    background: rgba(255,255,255,0.05);
    border-radius: 4px;
    overflow: hidden;
}
.ga4-pb-row__bar {
    height: 100%;
    border-radius: 4px;
    transition: width 0.3s ease;
}
.ga4-pb-row__share {
    text-align: right;
    color: rgba(145,160,185,0.75);
    font-size: 0.75rem;
}
.ga4-pb-row__count {
    text-align: right;
    color: rgba(185,195,215,0.7);
    font-size: 0.75rem;
    font-variant-numeric: tabular-nums;
}

/* ─── Channel Analytics Redesigned Layout ───────────────────────────────── */

/* Compact page header */
.ca-page-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    margin-bottom: 16px;
    flex-wrap: wrap;
}
.ca-page-header__left {
    display: flex;
    align-items: center;
    gap: 12px;
    flex-wrap: wrap;
}
.ca-page-header__title {
    margin: 0;
    font-size: 1.15rem;
    font-weight: 700;
    color: rgba(235,240,255,0.96);
    display: flex;
    align-items: center;
    gap: 10px;
}
.ca-page-header__channel {
    color: rgba(200,210,240,0.9);
    font-weight: 600;
}
.ca-back-btn {
    background: none;
    border: none;
    padding: 0;
    font-size: 0.82rem;
    font-weight: 600;
    color: rgba(145,160,200,0.75);
    cursor: pointer;
    white-space: nowrap;
    transition: color 0.12s;
}
.ca-back-btn:hover { color: rgba(200,210,240,0.95); }
.ca-compare-pill {
    display: inline-block;
    padding: 3px 10px;
    background: rgba(var(--sa-accent),0.12);
    border: 1px solid rgba(var(--sa-accent),0.25);
    border-radius: 20px;
    font-size: 0.71rem;
    color: rgba(var(--sa-accent),0.95);
}
.ca-reconcile-link {
    display: inline-block;
    padding: 6px 14px;
    background: rgba(var(--sa-accent),0.1);
    border: 1px solid rgba(var(--sa-accent),0.25);
    border-radius: 8px;
    font-size: 0.77rem;
    font-weight: 600;
    color: rgba(var(--sa-accent),0.95);
    text-decoration: none;
    transition: background 0.13s;
    white-space: nowrap;
}
.ca-reconcile-link:hover { background: rgba(var(--sa-accent),0.18); color: rgba(var(--sa-accent),1); }

/* Consent KPI strip */
.ca-kpi-strip {
    display: flex;
    gap: 0;
    margin-bottom: 16px;
    border: 1px solid rgba(255,255,255,0.07);
    border-radius: 12px;
    overflow: hidden;
}
.ca-kpi {
    flex: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 12px 8px;
    border-right: 1px solid rgba(255,255,255,0.06);
    cursor: default;
    min-width: 0;
    transition: background 0.12s;
}
.ca-kpi:last-child { border-right: none; }
.ca-kpi:hover { background: rgba(255,255,255,0.035); }
.ca-kpi__value {
    font-size: 1.3rem;
    font-weight: 700;
    color: rgba(232,236,248,0.95);
    letter-spacing: -0.025em;
    line-height: 1.1;
    white-space: nowrap;
}
.ca-kpi--warn .ca-kpi__value { color: rgba(252,165,50,0.92); }
.ca-kpi__label {
    font-size: 0.64rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: rgba(140,155,180,0.6);
    margin-top: 3px;
    text-align: center;
    line-height: 1.2;
}
.ca-kpi__compare {
    margin-top: 3px;
    font-size: 0.7rem;
}

/* Table section header with inline toolbar */
.ca-table-section { margin-bottom: 0; }
.ca-table-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    margin-bottom: 10px;
    flex-wrap: wrap;
}
.ca-table-toolbar {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
}

/* Collapsed context section */
.ca-context-details {
    margin: 16px 0 4px;
}
.ca-context-summary {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 10px 14px;
    background: rgba(255,255,255,0.03);
    border: 1px solid rgba(255,255,255,0.07);
    border-radius: 10px;
    cursor: pointer;
    font-size: 0.8rem;
    font-weight: 600;
    color: rgba(170,180,210,0.8);
    list-style: none;
    user-select: none;
    transition: background 0.12s;
}
.ca-context-summary::-webkit-details-marker { display: none; }
.ca-context-summary::before {
    content: "▸";
    font-size: 0.7rem;
    color: rgba(140,155,180,0.5);
    transition: transform 0.15s;
}
details[open] .ca-context-summary::before { content: "▾"; }
.ca-context-summary:hover { background: rgba(255,255,255,0.055); }
.ca-context-summary__hint {
    font-size: 0.69rem;
    font-weight: 400;
    color: rgba(130,145,170,0.55);
    margin-left: 4px;
}
.ca-context-details[open] .ca-context-summary {
    border-radius: 10px 10px 0 0;
    border-bottom: none;
}

/* ─── GA4 Coverage & Blindspots ─────────────────────────────────────────── */

.ga4-coverage {
    margin: 20px 0 0;
    padding: 16px 20px;
    background: rgba(255,255,255,0.025);
    border-radius: 10px;
    border: 1px solid rgba(255,255,255,0.07);
}
.ga4-coverage__header {
    display: flex;
    align-items: baseline;
    gap: 10px;
    margin-bottom: 14px;
}
.ga4-coverage__title {
    margin: 0;
    font-size: 0.75rem;
    font-weight: 700;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: rgba(var(--sa-accent),0.9);
}
.ga4-coverage__subtitle {
    font-size: 0.72rem;
    color: rgba(140,155,180,0.65);
}
.ga4-coverage__metrics {
    display: flex;
    gap: 0;
    flex-wrap: wrap;
    margin-bottom: 14px;
    border: 1px solid rgba(255,255,255,0.07);
    border-radius: 8px;
    overflow: hidden;
}
.ga4-coverage__metric {
    flex: 1;
    min-width: 90px;
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 10px 12px;
    border-right: 1px solid rgba(255,255,255,0.07);
    gap: 3px;
}
.ga4-coverage__metric:last-child { border-right: none; }
.ga4-coverage__metric--dark { background: rgba(239,68,68,0.05); }
.ga4-coverage__metric-value {
    font-size: 1.05rem;
    font-weight: 700;
    font-variant-numeric: tabular-nums;
    color: rgba(235,240,255,0.95);
    letter-spacing: -0.01em;
}
.ga4-coverage__metric--dark .ga4-coverage__metric-value {
    color: rgba(239,68,68,0.85);
}
.ga4-coverage__metric-label {
    font-size: 0.67rem;
    color: rgba(140,155,180,0.7);
    text-transform: uppercase;
    letter-spacing: 0.05em;
}
/* Stacked bar */
.ga4-coverage__bar-track {
    position: relative;
    height: 10px;
    background: rgba(239,68,68,0.2);
    border-radius: 6px;
    overflow: hidden;
    margin-bottom: 6px;
}
.ga4-coverage__bar-fill {
    position: absolute;
    left: 0; top: 0; bottom: 0;
    background: linear-gradient(90deg, rgba(74,222,128,0.75), rgba(34,197,94,0.65));
    border-radius: 6px;
    transition: width 0.4s ease;
    min-width: 2px;
}
.ga4-coverage__bar-legend {
    display: flex;
    gap: 16px;
    margin-bottom: 10px;
    font-size: 0.7rem;
}
.ga4-coverage__legend-consent::before {
    content: "■";
    color: rgba(74,222,128,0.75);
    margin-right: 4px;
}
.ga4-coverage__legend-dark::before {
    content: "■";
    color: rgba(239,68,68,0.4);
    margin-right: 4px;
}
.ga4-coverage__legend-consent { color: rgba(165,185,215,0.75); }
.ga4-coverage__legend-dark    { color: rgba(165,185,215,0.75); }
.ga4-coverage__note {
    margin: 0;
