}
.sa-perf-timing-card__sub {
    font-size: 10px;
    color: rgba(var(--sa-text-muted),0.55);
    text-transform: uppercase;
    letter-spacing: 0.05em;
}
.sa-perf-timing-card__value {
    margin-top: 4px;
    font-size: 15px;
    font-weight: 600;
}
.sa-perf-rating-wrap {
    display: flex;
    flex-direction: column;
    gap: 8px;
}
.sa-perf-rating-bar {
