    margin-right: 5px;
    vertical-align: middle;
}
.sa-perf-dot--good { background: rgba(34,197,94,0.75); }
.sa-perf-dot--ni   { background: rgba(234,179,8,0.75); }
.sa-perf-dot--poor { background: rgba(239,68,68,0.75); }
.sa-perf-empty {
    padding: 40px 24px;
    text-align: center;
    color: rgba(160,160,180,0.7);
}
.sa-perf-empty h3 { margin: 0 0 10px; color: rgba(200,200,220,0.8); }
.sa-perf-empty p  { margin: 0 0 8px; font-size: 14px; }
.sa-table__sortable { user-select: none; }
.sa-table__sortable--active { color: rgba(var(--sa-accent),0.9); }
.sa-perf-badge {
    display: inline-block;
    font-size: 10px;
    padding: 1px 6px;
    border-radius: 4px;
    background: rgba(255,255,255,0.07);
    color: rgba(180,180,200,0.75);
    border: 1px solid rgba(255,255,255,0.08);
    white-space: nowrap;
}
.sa-perf-badge--warn {
