    color: rgba(234,179,8,0.8);
    border-color: rgba(234,179,8,0.2);
}
.sa-table-pager {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 8px;
    padding: 8px 4px 2px;
}
.sa-table-pager__btn {
    background: rgba(255,255,255,0.07);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 6px;
    color: rgba(200,200,220,0.85);
    font-size: 16px;
    line-height: 1;
    padding: 2px 10px 4px;
