/* ── Country detail back bar ─────────────────────────────────────────── */
.sa-perf-back {
    display: flex;
    align-items: center;
    gap: 20px;
    padding: 10px 0 4px;
}
.sa-perf-back__btn {
    background: none;
    border: 1px solid rgba(255,255,255,0.12);
    border-radius: 6px;
    color: rgba(200,200,220,0.7);
