.sa-perf-2col {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
    gap: 20px;
    align-items: start;
}

/* ── Sparkline trend grid ─────────────────────────────────────────────── */
.sa-perf-sparklines {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
