/* ── Section labels ───────────────────────────────────────────────────────── */
.sa-perf-section-label {
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: rgba(160,160,180,0.45);
    margin-bottom: 8px;
    padding-left: 2px;
}

/* ── Period-over-period delta chip ────────────────────────────────────────── */
.sa-perf-delta {
    display: inline-block;
    font-size: 13px;
    font-weight: 600;
    margin-left: 8px;
    vertical-align: middle;
}
.sa-perf-cwv-card__value .sa-perf-delta {
    font-size: 14px;
}
.sa-perf-timing-card__value .sa-perf-delta {
    font-size: 11px;
    margin-left: 5px;
}

/* ── Sparkline band chart label ───────────────────────────────────────────── */
.sa-perf-sparkline-p75 {
    font-size: 9px;
    opacity: 0.5;
    font-weight: 400;
}

/* ── Percentile range bar ─────────────────────────────────────────────────── */
.sa-pctile-range-wrap {
    position: relative;
    height: 10px;
    background: rgba(255,255,255,0.04);
    border-radius: 3px;
    overflow: visible;
    min-width: 100px;
}
.sa-pctile-range-bg {
    position: absolute;
    inset: 0;
    display: flex;
    border-radius: 3px;
    overflow: hidden;
}
.sa-pctile-range-bar {
    position: absolute;
    top: 1px;
    bottom: 1px;
    background: rgba(var(--sa-accent),0.35);
    border-radius: 2px;
    min-width: 3px;
}
.sa-pctile-range-tick {
    position: absolute;
    top: -1px;
    bottom: -1px;
    width: 2px;
    background: rgba(var(--sa-accent),0.85);
    border-radius: 1px;
    transform: translateX(-50%);
