/* ── PageTable LCP range bar ──────────────────────────────────────────────── */
.sa-page-lcp-bar {
    position: relative;
    height: 8px;
    background: rgba(255,255,255,0.06);
    border-radius: 3px;
    min-width: 80px;
    overflow: visible;
}

