.sa-blocker-bar-wrap {
    flex: 1;
    height: 6px;
    background: rgba(255,255,255,0.06);
    border-radius: 3px;
    overflow: hidden;
    min-width: 40px;
    max-width: 80px;
}
.sa-blocker-bar {
    height: 100%;
    border-radius: 3px;
    transition: width 0.3s;
    min-width: 2px;
}

