    margin-bottom: 4px;
}
.pxp-cwv-supporting strong {
    color: rgba(220,220,240,0.88);
    font-weight: 600;
}

@media (max-width: 640px) {
    .pxp-cwv-detail-grid { grid-template-columns: 1fr 1fr; }
}

/* ── Page Weight — treemap ────────────────────────────────────────────────── */
.sa-treemap-wrap {
    border: 1px solid rgba(255,255,255,0.07);
    border-radius: 8px;
    overflow: hidden;
    background: rgba(0,0,0,0.15);
}
.sa-treemap-svg {
    width: 100%;
    height: auto;
    aspect-ratio: 960 / 420;
    display: block;
}
.sa-treemap-legend {
    display: flex;
    flex-wrap: wrap;
    gap: 8px 18px;
    margin-top: 14px;
}
.sa-treemap-legend__item {
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 12px;
    color: rgba(200,200,220,0.8);
}
.sa-treemap-legend__swatch {
    width: 10px;
    height: 10px;
    border-radius: 3px;
    flex-shrink: 0;
}
.sa-treemap-legend__label {
    font-weight: 600;
}
.sa-treemap-legend__value {
    color: rgba(200,200,220,0.6);
}
.sa-treemap-legend__pct {
    font-size: 11px;
}

/* ── Page Weight — diagnostics & recommendations ──────────────────────────── */
.sa-diag-list {
    display: flex;
    flex-direction: column;
    gap: 10px;
}
.sa-diag-item {
    background: rgba(255,255,255,0.03);
    border: 1px solid rgba(255,255,255,0.07);
    border-left-width: 3px;
    border-radius: 6px;
    padding: 10px 14px;
}
.sa-diag-item__head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    margin-bottom: 4px;
}
.sa-diag-item__title {
    font-size: 13px;
    font-weight: 700;
    color: rgba(230,230,245,0.92);
}
.sa-diag-item__detail {
    margin: 0 0 8px;
    font-size: 12.5px;
    line-height: 1.5;
    color: rgba(190,190,210,0.75);
}
.sa-diag-item__savings {
    display: flex;
    align-items: baseline;
    gap: 8px;
    font-size: 12px;
}
.sa-diag-item__savings-label {
    color: rgba(160,160,180,0.6);
    text-transform: uppercase;
    letter-spacing: 0.04em;
    font-size: 10px;
}
.sa-diag-item__savings-value {
    font-weight: 700;
    color: rgba(var(--sa-accent),0.95);
}

/* ── Channel Digest page ─────────────────────────────────────────────────────── */

.sa-subnav__tab--portfolio {
    margin-left: auto;
    padding-left: 16px;
    border-left: 1px solid rgba(255,255,255,0.06);
}

.sa-digest-meta {
    display: flex;
    align-items: center;
    gap: 12px;
    margin: 10px 0 16px;
}
.sa-digest-meta__info {
    font-size: 0.78rem;
    color: rgba(155,155,175,0.55);
}
.sa-digest-meta__refresh {
    background: rgba(255,255,255,0.05);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 6px;
    color: rgba(200,200,220,0.7);
    font-size: 0.75rem;
    padding: 3px 10px;
    cursor: pointer;
    transition: background 0.12s;
}
.sa-digest-meta__refresh:hover { background: rgba(255,255,255,0.09); }
.sa-digest-meta__refresh:disabled { opacity: 0.4; cursor: default; }

.sa-digest-section { margin-top: 8px; }

.sa-digest-card { position: relative; }
.sa-digest-card__domain {
    display: inline-block;
    font-size: 0.68rem;
    color: rgba(var(--sa-accent),0.65);
    background: rgba(var(--sa-accent),0.08);
    border: 1px solid rgba(var(--sa-accent),0.15);
    border-radius: 4px;
    padding: 1px 6px;
    margin-bottom: 6px;
    font-family: monospace;
    letter-spacing: 0.02em;
}
