argin-top: 6px;\n    font-size: 0.72rem;\n    color: rgba(var(--sa-text-dim),0.75);\n}\n\n.sa-benchmark-note__diff {\n    font-weight: 700;\n}\n\n.sa-benchmark-note__diff--up   { color: rgba(74,222,128,0.9); }\n.sa-benchmark-note__diff--down { color: rgba(248,113,113,0.9); }\n\n/* ── Variant detail page ──────────────────────────────────────────────────── */\n.pxp-detail__title {\n    display: flex;\n    align-items: center;\n    gap: 10px;\n}\n\n.pxp-detail__section-title {\n    margin: 22px 0 10px;\n    font-size: 0.85rem;\n    font-weight: 600;\n    color: rgba(var(--sa-text),0.85);\n}\n\n.pxp-detail-stats {\n    display: grid;\n    grid-template-columns: repeat(4, 1fr);\n    gap: 10px;\n}\n\n.pxp-detail-stat {\n    display: flex;\n    flex-direction: column;\n    gap: 3px;\n    padding: 12px 10px;\n    border-radius: 10px;\n    border: 1px solid rgba(255,255,255,0.08);\n    background: rgba(255,255,255,0.03);\n    text-align: center;\n}\n\n.pxp-detail-stat__value {\n    font-size: 1.15rem;\n    font-weight: 700;\n    color: #ececec;\n}\n\n.pxp-detail-stat__label {\n    font-size: 0.68rem;\n    color: rgba(var(--sa-text-muted),0.7);\n}\n\n.pxp-detail-clicks {\n    list-style: none;\n    margin: 0;\n    padding: 0;\n    display: flex;\n    flex-direction: column;\n    gap: 6px;\n}\n\n.pxp-detail-clicks__row {\n    display: flex;\n    align-items: baseline;\n    gap: 8px;\n    font-size: 0.8rem;\n    padding: 8px 10px;\n    border-radius: 8px;\n    background: rgba(255,255,255,0.03);\n}\n\n.pxp-detail-clicks__selector {\n    color: rgba(var(--sa-accent),0.9);\n    font-size: 0.76rem;\n    flex-shrink: 0;\n}\n\n.pxp-detail-clicks__text {\n    color: rgba(var(--sa-text-secondary),0.75);\n    overflow: hidden;\n    text-overflow: ellipsis;\n    white-space: nowrap;\n    flex: 1;\n}\n\n.pxp-detail-clicks__n {\n    margin-left: auto;\n    color: rgba(var(--sa-text),0.6);\n    font-size: 0.72rem;\n    flex-shrink: 0;\n}\n\n/* ── Enhanced click table ─────────────────────