    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 6px;
    padding: 10px 0 16px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.05);
    margin-bottom: 4px;
}

.compliance-transfers__history-label {
    font-size: 0.65rem;
    font-weight: 700;
    letter-spacing: 0.09em;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.2);
    margin-right: 4px;
    flex-shrink: 0;
}

.compliance-transfers__history-chip {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 4px 10px;
    border-radius: 6px;
    border: 1px solid rgba(255, 255, 255, 0.07);
    background: rgba(255, 255, 255, 0.02);
    font-size: 0.7rem;
    color: rgba(255, 255, 255, 0.35);
}

.compliance-transfers__history-chip-detail {
    color: rgba(255, 255, 255, 0.2);
}

/* ── Search input ────────────────────────────────────────────────────────────── */
.compliance-search {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 10px;
}

.compliance-search__input {
    flex: 1;
    padding: 8px 12px;
    border-radius: 7px;
    border: 1px solid rgba(255, 255, 255, 0.09);
    background: rgba(255, 255, 255, 0.03);
    color: rgba(255, 255, 255, 0.75);
    font-size: 0.8rem;
    font-family: inherit;
    outline: none;
    transition: border-color 0.15s ease, background 0.15s ease;
    min-width: 0;
}

.compliance-search__input::placeholder {
    color: rgba(255, 255, 255, 0.2);
}

.compliance-search__input:focus {
    border-color: rgba(192, 159, 83, 0.4);
    background: rgba(255, 255, 255, 0.05);
}

.compliance-search__input::-webkit-search-cancel-button {
    filter: invert(0.5);
    cursor: pointer;
}

.compliance-search__count {
    font-size: 0.68rem;
    color: rgba(255, 255, 255, 0.3);
    white-space: nowrap;
    flex-shrink: 0;
}

/* ── List column headers ─────────────────────────────────────────────────────── */
.compliance-transfers__list-header {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 4px 14px 6px;
    font-size: 0.6rem;
    font-weight: 700;
    letter-spacing: 0.09em;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.2);
}

.compliance-transfers__list-header > span:first-child { width: 18px; flex-shrink: 0; }
.compliance-transfers__list-header > span:nth-child(2) { flex: 1; min-width: 0; }
.compliance-transfers__list-header > span:last-child   { width: 18px; flex-shrink: 0; }

.compliance-cookies__list-header {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 4px 14px 6px;
    font-size: 0.6rem;
    font-weight: 700;
    letter-spacing: 0.09em;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.2);
}

.compliance-cookies__list-header > span:first-child { flex: 1; min-width: 0; }

/* ── Expandable transfer rows ────────────────────────────────────────────────── */
.compliance-transfers__row-wrap {
    display: flex;
    flex-direction: column;
}

.compliance-transfers__row {
    cursor: pointer;
    transition: background 0.12s ease, border-color 0.12s ease;
}

.compliance-transfers__row:hover,
.compliance-transfers__row.--expanded {
    background: rgba(255, 80, 80, 0.08);
    border-color: rgba(255, 80, 80, 0.22);
}

.compliance-transfers__row-toggle {
    flex-shrink: 0;
    font-size: 0.65rem;
    color: rgba(255, 255, 255, 0.25);
    width: 14px;
    text-align: center;
    transition: color 0.12s ease;
}

.compliance-transfers__row:hover .compliance-transfers__row-toggle,
.compliance-transfers__row.--expanded .compliance-transfers__row-toggle {
    color: rgba(255, 255, 255, 0.5);
}

.compliance-transfers__row-detail {
    display: flex;
    flex-wrap: wrap;
    gap: 10px 20px;
    padding: 10px 14px 12px 44px;
    border: 1px solid rgba(255, 80, 80, 0.12);
    border-top: none;
    border-radius: 0 0 8px 8px;
    background: rgba(255, 255, 255, 0.02);
}

.compliance-transfers__row-detail-item {
    display: flex;
    flex-direction: column;
    gap: 3px;
    font-size: 0.75rem;
    color: rgba(255, 255, 255, 0.55);
}

.compliance-transfers__row-detail-item--full {
    width: 100%;
}

.compliance-transfers__row-detail-label {
    font-size: 0.58rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.2);
}

.compliance-transfers__row-detail-code {
    font-family: monospace;
    font-size: 0.72rem;
    color: rgba(192, 159, 83, 0.75);
    word-break: break-all;
    white-space: pre-wrap;
}

.compliance-transfers__row-detail-privacy {
    font-size: 0.72rem;
    color: rgba(80, 144, 220, 0.8);
    text-decoration: none;
}
.compliance-transfers__row-detail-privacy:hover {
    color: rgba(80, 144, 220, 1);
    text-decoration: underline;
}

/* ── Consent / banner category badge ────────────────────────────────────────── */
.compliance-banner-cat {
    flex-shrink: 0;
    padding: 2px 8px;
    border-radius: 5px;
    font-size: 0.6rem;
    font-weight: 700;
    letter-spacing: 0.07em;
    text-transform: uppercase;
    white-space: nowrap;
    border: 1px solid color-mix(in srgb, var(--bc-color, #909090) 35%, transparent);
    background: color-mix(in srgb, var(--bc-color, #909090) 10%, transparent);
    color: color-mix(in srgb, var(--bc-color, #909090) 90%, #fff);
}

/* ── Pagination controls ─────────────────────────────────────────────────────── */
.compliance-pagination {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
    padding: 14px 0 2px;
}

.compliance-pagination__btn {
    padding: 5px 14px;
    border-radius: 6px;
    border: 1px solid rgba(255, 255, 255, 0.09);
    background: transparent;
    color: rgba(255, 255, 255, 0.45);
    font-size: 0.75rem;
    font-family: inherit;
    cursor: pointer;
    transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease;
}

.compliance-pagination__btn:hover:not(:disabled) {
    background: rgba(255, 255, 255, 0.06);
    color: rgba(255, 255, 255, 0.75);
    border-color: rgba(255, 255, 255, 0.16);
}

.compliance-pagination__btn:disabled {
    opacity: 0.25;
    cursor: not-allowed;
}

.compliance-pagination__info {
    font-size: 0.72rem;
    color: rgba(255, 255, 255, 0.3);
    font-variant-numeric: tabular-nums;
    min-width: 52px;
    text-align: center;
}

/* ── Embed modal ─────────────────────────────────────────────────────────────── */
.compliance-embed-modal__overlay {
    position: fixed;
    inset: 0;
    z-index: 1000;
    background: rgba(0, 0, 0, 0.65);
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 24px;
}

.compliance-embed-modal {
    background: #1a1a2e;
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    padding: 28px 28px 24px;
    width: 100%;
    max-width: 560px;
    box-shadow: 0 24px 64px rgba(0, 0, 0, 0.5);
}

.compliance-embed-modal__header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 12px;
}

.compliance-embed-modal__title {
    font-size: 0.95rem;
    font-weight: 700;
    color: rgba(255, 255, 255, 0.9);
    margin: 0;
}

.compliance-embed-modal__close {
    background: none;
    border: none;
    color: rgba(255, 255, 255, 0.35);
    font-size: 1rem;
    cursor: pointer;
    padding: 4px;
    line-height: 1;
    transition: color 0.15s ease;
}

.compliance-embed-modal__close:hover {
    color: rgba(255, 255, 255, 0.75);
}

.compliance-embed-modal__desc {
    font-size: 0.82rem;
    color: rgba(255, 255, 255, 0.5);
    margin: 0 0 16px;
    line-height: 1.55;
}

.compliance-embed-modal__desc strong {
    color: rgba(255, 255, 255, 0.8);
    font-weight: 600;
}

.compliance-embed-modal__code {
    background: rgba(0, 0, 0, 0.35);
    border: 1px solid rgba(255, 255, 255, 0.07);
    border-radius: 8px;
    padding: 14px 16px;
    font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
    font-size: 0.75rem;
    color: rgba(255, 255, 255, 0.75);
    white-space: pre-wrap;
    word-break: break-all;
    margin: 0 0 16px;
    line-height: 1.6;
}

.compliance-embed-modal__actions {
    display: flex;
    justify-content: flex-end;
    margin-bottom: 14px;
}

.compliance-embed-modal__copy-btn {
    padding: 9px 18px;
    border-radius: 8px;
    border: none;
    background: rgba(255, 255, 255, 0.1);
    color: rgba(255, 255, 255, 0.85);
    font-size: 0.8rem;
    font-weight: 600;
    font-family: inherit;
    cursor: pointer;
    letter-spacing: 0.02em;
    transition: background 0.15s ease, color 0.15s ease;
}

.compliance-embed-modal__copy-btn:hover {
    background: rgba(255, 255, 255, 0.16);
}

.compliance-embed-modal__hint {
    font-size: 0.75rem;
    color: rgba(255, 255, 255, 0.28);
    margin: 0;
    line-height: 1.5;
}

.compliance-embed-modal__hint code {
    font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
    font-size: 0.72rem;
    background: rgba(255, 255, 255, 0.06);
    padding: 1px 5px;
    border-radius: 4px;
}

/* ── Cookie table actions gap ────────────────────────────────────────────────── */
.compliance-cookies__table-actions {
    gap: 8px;
}

/* ── Cookie row wrap ─────────────────────────────────────────────────────────── */
.compliance-cookies__row-wrap {
    display: flex;
    flex-direction: column;
}

.compliance-cookies__row--unknown {
    border-color: rgba(220, 160, 60, 0.2);
    background: rgba(220, 160, 60, 0.04);
    border-left: 3px solid rgba(220, 160, 60, 0.35);
}

/* ── Vendor line in cookie row ───────────────────────────────────────────────── */
.compliance-cookies__row-vendor {
    font-size: 0.65rem;
    color: rgba(192, 159, 83, 0.7);
    font-weight: 600;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

/* ── Unknown category badge ──────────────────────────────────────────────────── */
.compliance-cookies__unknown-badge {
    flex-shrink: 0;
    padding: 2px 8px;
    border-radius: 5px;
    font-size: 0.6rem;
    font-weight: 700;
    letter-spacing: 0.07em;
    text-transform: uppercase;
    white-space: nowrap;
    border: 1px solid rgba(220, 160, 60, 0.22);
    background: rgba(220, 160, 60, 0.06);
    color: rgba(230, 180, 100, 0.55);
}

/* ── Edit button on cookie row ───────────────────────────────────────────────── */
.compliance-cookies__edit-btn {
    flex-shrink: 0;
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 5px;
    color: rgba(255, 255, 255, 0.3);
    font-size: 0.8rem;
    width: 24px;
    height: 24px;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    font-family: inherit;
    padding: 0;
    line-height: 1;
    transition: color 0.12s ease, border-color 0.12s ease, background 0.12s ease;
}

.compliance-cookies__row--unknown .compliance-cookies__edit-btn {
    background: rgba(220, 160, 60, 0.07);
    border-color: rgba(220, 160, 60, 0.25);
    color: rgba(220, 160, 60, 0.6);
}

.compliance-cookies__edit-btn:hover,
.compliance-cookies__edit-btn.--active {
    color: rgba(192, 159, 83, 0.9);
    border-color: rgba(192, 159, 83, 0.35);
    background: rgba(192, 159, 83, 0.08);
}

/* ── Inline edit panel ───────────────────────────────────────────────────────── */
.compliance-cookies__edit-panel {
    display: flex;
    align-items: flex-end;
    gap: 10px;
    padding: 10px 14px 12px;
    border: 1px solid rgba(192, 159, 83, 0.15);
    border-top: none;
    border-radius: 0 0 8px 8px;
    background: rgba(192, 159, 83, 0.03);
    flex-wrap: wrap;
}

.compliance-cookies__edit-fields {
    display: flex;
    gap: 10px;
    flex: 1;
    flex-wrap: wrap;
    min-width: 0;
}

.compliance-cookies__edit-field {
    display: flex;
    flex-direction: column;
    gap: 4px;
    min-width: 120px;
}

.compliance-cookies__edit-field--wide {
    flex: 1;
    min-width: 180px;
}

.compliance-cookies__edit-label {
    font-size: 0.58rem;
    font-weight: 700;
    letter-spacing: 0.09em;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.22);
}

.compliance-cookies__edit-input,
.compliance-cookies__edit-select {
    padding: 6px 10px;
    border-radius: 6px;
    border: 1px solid rgba(255, 255, 255, 0.09);
    background: rgba(255, 255, 255, 0.04);
    color: rgba(255, 255, 255, 0.75);
    font-size: 0.78rem;
    font-family: inherit;
    outline: none;
    transition: border-color 0.15s ease;
}

.compliance-cookies__edit-input:focus,
.compliance-cookies__edit-select:focus {
    border-color: rgba(192, 159, 83, 0.4);
}

.compliance-cookies__edit-select option {
    background: #1a1a2e;
    color: rgba(255, 255, 255, 0.75);
}

.compliance-cookies__edit-actions {
    display: flex;
    gap: 6px;
    flex-shrink: 0;
    align-items: flex-end;
}

.compliance-cookies__edit-save {
    padding: 6px 14px;
    border-radius: 6px;
    border: 1px solid rgba(192, 159, 83, 0.35);
    background: rgba(192, 159, 83, 0.1);
    color: #c0a053;
    font-size: 0.75rem;
    font-weight: 600;
    font-family: inherit;
    cursor: pointer;
    letter-spacing: 0.02em;
    transition: background 0.15s ease, border-color 0.15s ease;
}

.compliance-cookies__edit-save:hover {
    background: rgba(192, 159, 83, 0.18);
    border-color: rgba(192, 159, 83, 0.55);
}

.compliance-cookies__edit-cancel {
    padding: 6px 12px;
    border-radius: 6px;
    border: 1px solid rgba(255, 255, 255, 0.08);
    background: transparent;
    color: rgba(255, 255, 255, 0.35);
    font-size: 0.75rem;
    font-family: inherit;
    cursor: pointer;
    transition: color 0.15s ease, background 0.15s ease;
}

.compliance-cookies__edit-cancel:hover {
    background: rgba(255, 255, 255, 0.05);
    color: rgba(255, 255, 255, 0.6);
